151	</head>
152	<body>
153	  <a class="skip-link" href="#main">Skip to content</a>
154	  <nav aria-label="Primary">
155	    <ul>
156	      <li><a href="#home" data-nav-link>Home</a></li>
157	      <li><a href="#about" data-nav-link>About</a></li>
158	      <li><a href="#contact" data-nav-link>Contact</a></li>
159	    </ul>
160	  </nav>
161	  <main id="main">
162	    <section id="home" aria-labelledby="home-heading">
163	      <h1 id="home-heading">My Page</h1>
164	      <p>Welcome. This page is a starting point — replace this text with your own content.</p>
165	    </section>
166	
167	    <section id="about" aria-labelledby="about-heading">
168	      <h2 id="about-heading">About</h2>
169	      <p>Add a short description of what this page or project is about here.</p>
170	    </section>
171	
172	    <section id="contact" aria-labelledby="contact-heading">
173	      <h2 id="contact-heading">Contact</h2>
174	      <p>Reach out at <a href="mailto:hello@example.com">hello@example.com</a>.</p>
175	    </section>
176	  </main>
177	  <footer>
178	    <p>&copy; <span id="year"></span> My Page. All rights reserved.</p>
179	  </footer>
180	  <script>
181	    document.getElementById('year').textContent = String(new Date().getFullYear());
182	
183	    const navLinks = document.querySelectorAll('[data-nav-link]');
184	    const sections = [...navLinks].map(link => document.querySelector(link.getAttribute('href')));
185	
186	    const setActive = (id) => {
187	      navLinks.forEach(link => {
188	        if (link.getAttribute('href') === `#${id}`) {
189	          link.setAttribute('aria-current', 'true');
190	        } else {
191	          link.removeAttribute('aria-current');
192	        }
193	      });
194	    };
195	
196	    if ('IntersectionObserver' in window) {
197	      const observer = new IntersectionObserver((entries) => {
198	        const visible = entries.find(entry => entry.isIntersecting);
199	        if (visible) setActive(visible.target.id);
200	      }, { rootMargin: '-40% 0px -50% 0px' });
201	      sections.forEach(section => section && observer.observe(section));
202	    }
203	  </script>
204	</body>
205	</html>
